{
  "commit": "b99a19a2d160b6296029cef915338f1423257a27",
  "short": "b99a19a2d160",
  "author": "Bianque Demo",
  "date": "2026-10-19T22:36:48Z",
  "message": "Add s1-app manifests",
  "diff": "diff --git a/00-namespace.yaml b/00-namespace.yaml\nnew file mode 100644\nindex 0000000..8d46544\n--- /dev/null\n+++ b/00-namespace.yaml\n@@ -0,0 +1,4 @@\n+apiVersion: v1\n+kind: Namespace\n+metadata:\n+  name: demo-s1\ndiff --git a/README.md b/README.md\nnew file mode 100644\nindex 0000000..f44026a\n--- /dev/null\n+++ b/README.md\n@@ -0,0 +1,9 @@\n+# s1-app manifests\n+\n+Deployment manifests for s1-app in the `demo-s1` namespace. Every change is\n+committed here and then applied with `kubectl apply -f .`.\n+\n+- `00-namespace.yaml`: the namespace (applied first; `kubectl apply -f .` goes\n+  through the files in name order)\n+- `deployment.yaml`: the application and its configuration\n+- `service.yaml`: the in-cluster service on port 80\ndiff --git a/deployment.yaml b/deployment.yaml\nnew file mode 100644\nindex 0000000..818c3e9\n--- /dev/null\n+++ b/deployment.yaml\n@@ -0,0 +1,48 @@\n+apiVersion: apps/v1\n+kind: Deployment\n+metadata:\n+  name: s1-app\n+  namespace: demo-s1\n+  labels:\n+    app.kubernetes.io/name: s1-app\n+spec:\n+  replicas: 1\n+  selector:\n+    matchLabels:\n+      app.kubernetes.io/name: s1-app\n+  template:\n+    metadata:\n+      labels:\n+        app.kubernetes.io/name: s1-app\n+    spec:\n+      containers:\n+        - name: app\n+          image: bianque-s1-app:dev\n+          imagePullPolicy: Never\n+          ports:\n+            - name: http\n+              containerPort: 8080\n+          env:\n+            - name: APP_MODE\n+              value: standard\n+            - name: ALLOC_MB\n+              value: \"48\"\n+          resources:\n+            requests:\n+              memory: 64Mi\n+              cpu: 50m\n+            limits:\n+              memory: 128Mi\n+              cpu: 200m\n+          livenessProbe:\n+            httpGet:\n+              path: /healthz\n+              port: http\n+            initialDelaySeconds: 3\n+            periodSeconds: 5\n+            failureThreshold: 2\n+          readinessProbe:\n+            httpGet:\n+              path: /healthz\n+              port: http\n+            periodSeconds: 5\ndiff --git a/service.yaml b/service.yaml\nnew file mode 100644\nindex 0000000..eaa45ee\n--- /dev/null\n+++ b/service.yaml\n@@ -0,0 +1,14 @@\n+apiVersion: v1\n+kind: Service\n+metadata:\n+  name: s1-app\n+  namespace: demo-s1\n+  labels:\n+    app.kubernetes.io/name: s1-app\n+spec:\n+  selector:\n+    app.kubernetes.io/name: s1-app\n+  ports:\n+    - name: http\n+      port: 80\n+      targetPort: http",
  "diff_truncated": false
}

